css:
  :root {
    --paper: #F5F2EA;
    --paper-2: #EEEADF;
    --card: #FFFCF5;
    --ink: #15211B;
    --ink-2: #435047;
    --ink-3: #5F6A62;
    --line: #D9D3C4;
    --line-strong: #C6BFAE;
    --green: #0E5B44;
    --green-dark: #0A3E30;
    --green-deep: #08251D;
    --mint: #DCE8DE;
    --sage: #E5EADF;
    --lime: #DCEB9C;
    --amber: #8A4E12;
    --amber-bg: #F7E8CF;
    --white: #FFFDF6;
    --font-sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --font-serif: 'Iowan Old Style', 'Palatino Linotype', 'Book Antiqua', Palatino, Georgia, serif;
    --font-mono: ui-monospace, 'SFMono-Regular', Menlo, Consolas, 'Liberation Mono', monospace;
    --radius: 10px;
    --max: 1180px;
    --gutter: clamp(20px, 4vw, 40px);
    --section-pad: clamp(64px, 9vw, 112px);
  }

  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
    scroll-padding-top: 76px;
    -webkit-text-size-adjust: 100%;
  }

  body {
    margin: 0;
    background: var(--paper);
    color: var(--ink);
    font-family: var(--font-sans);
    font-size: 16px;
    line-height: 1.55;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: clip;
  }

  ::selection {
    background: var(--lime);
    color: var(--ink);
  }

  h1,
  h2,
  h3,
  p {
    margin-top: 0;
  }

  a {
    color: inherit;
  }

  svg {
    display: block;
    flex: 0 0 auto;
  }

  .wrap {
    width: calc(100% - (var(--gutter) * 2));
    max-width: var(--max);
    margin-inline: auto;
  }

  .skip-link {
    position: fixed;
    top: -80px;
    left: 16px;
    z-index: 100;
    padding: 12px 18px;
    border-radius: 8px;
    background: var(--ink);
    color: var(--paper);
    font-size: 0.9rem;
    font-weight: 600;
    text-decoration: none;
    transition: top 0.18s ease;
  }

  .skip-link:focus {
    top: 16px;
  }

  .skip-link:focus-visible {
    outline-color: var(--lime);
  }

  :focus-visible {
    outline: 2px solid var(--green);
    outline-offset: 3px;
  }

  .closing :focus-visible {
    outline-color: var(--lime);
  }

  /* Header */
  .site-header {
    position: sticky;
    top: 0;
    z-index: 50;
    background: rgba(245, 242, 234, 0.86);
    -webkit-backdrop-filter: blur(14px);
    backdrop-filter: blur(14px);
    border-bottom: 1px solid rgba(198, 191, 174, 0.62);
  }

  .header-inner {
    display: flex;
    align-items: center;
    gap: 30px;
    min-height: 72px;
  }

  .brand {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    min-height: 44px;
    border-radius: 6px;
    color: var(--ink);
    font-size: 1.08rem;
    font-weight: 650;
    letter-spacing: -0.025em;
    text-decoration: none;
  }

  .brand svg {
    width: 28px;
    height: 28px;
  }

  .nav {
    display: flex;
    align-items: center;
    gap: 28px;
    margin-left: 6px;
  }

  .nav a {
    position: relative;
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    color: var(--ink-2);
    font-size: 0.92rem;
    font-weight: 500;
    text-decoration: none;
  }

  .nav a::after {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    bottom: 10px;
    height: 1px;
    background: var(--green);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.2s ease;
  }

  .nav a:hover {
    color: var(--ink);
  }

  .nav a:hover::after {
    transform: scaleX(1);
  }

  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    min-height: 48px;
    padding: 0 22px;
    border: 1px solid transparent;
    border-radius: var(--radius);
    font-family: inherit;
    font-size: 0.95rem;
    font-weight: 650;
    letter-spacing: -0.01em;
    line-height: 1;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color 0.18s ease, border-color 0.18s ease, color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
  }

  .btn svg {
    width: 17px;
    height: 17px;
    transition: transform 0.18s ease;
  }

  .btn:hover svg {
    transform: translateX(2px);
  }

  .btn:active {
    transform: translateY(1px);
  }

  .btn-primary {
    background: var(--green);
    color: var(--white);
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.12) inset, 0 10px 24px -14px rgba(14, 91, 68, 0.8);
  }

  .btn-primary:hover {
    background: var(--green-dark);
    transform: translateY(-1px);
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.12) inset, 0 16px 30px -16px rgba(14, 91, 68, 0.75);
  }

  .btn-secondary {
    background: transparent;
    border-color: rgba(21, 33, 27, 0.26);
    color: var(--ink);
  }

  .btn-secondary:hover {
    background: rgba(21, 33, 27, 0.05);
    border-color: rgba(21, 33, 27, 0.44);
  }

  .btn-header {
    min-height: 44px;
    margin-left: auto;
    padding: 0 17px;
    font-size: 0.86rem;
  }

  .btn-header svg {
    width: 15px;
    height: 15px;
  }

  .btn-light {
    background: var(--paper);
    color: var(--green-deep);
  }

  .btn-light:hover {
    background: var(--white);
    transform: translateY(-1px);
    box-shadow: 0 14px 28px -18px rgba(0, 0, 0, 0.65);
  }

  .btn-outline-light {
    background: transparent;
    border-color: rgba(245, 242, 234, 0.42);
    color: var(--paper);
  }

  .btn-outline-light:hover {
    background: rgba(245, 242, 234, 0.09);
    border-color: rgba(245, 242, 234, 0.68);
  }

  /* Shared type */
  .eyebrow {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 0 0 14px;
    color: var(--green);
    font-family: var(--font-mono);
    font-size: 0.68rem;
    font-weight: 600;
    letter-spacing: 0.16em;
    text-transform: uppercase;
  }

  .eyebrow::before {
    content: '';
    width: 22px;
    height: 1px;
    background: currentColor;
  }

  .eyebrow--light {
    color: var(--lime);
  }

  h2 {
    font-family: var(--font-serif);
    font-size: clamp(2rem, 4vw, 3.2rem);
    font-weight: 400;
    line-height: 1.03;
    letter-spacing: -0.03em;
    text-wrap: balance;
  }

/* Hero */
  .hero {
    position: relative;
    overflow: clip;
    padding: clamp(44px, 6.5vw, 82px) 0 clamp(66px, 9vw, 112px);
  }

  .hero::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background-image: linear-gradient(to right, rgba(21, 33, 27, 0.045) 1px, transparent 1px), linear-gradient(to bottom, rgba(21, 33, 27, 0.045) 1px, transparent 1px);
    background-size: 48px 48px;
    -webkit-mask-image: radial-gradient(ellipse 68% 66% at 72% 34%, #000 8%, transparent 74%);
    mask-image: radial-gradient(ellipse 68% 66% at 72% 34%, #000 8%, transparent 74%);
  }

  .hero-glow {
    position: absolute;
    top: -26%;
    right: -8%;
    width: min(46vw, 620px);
    aspect-ratio: 1;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(14, 91, 68, 0.12), rgba(14, 91, 68, 0) 66%);
    pointer-events: none;
  }

  .hero-grid {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1.04fr) minmax(0, 0.96fr);
    gap: clamp(40px, 6vw, 84px);
    align-items: center;
  }

  .hero-copy {
    min-width: 0;
  }

  h1 {
    margin: 0;
    font-family: var(--font-serif);
    font-size: clamp(2.8rem, 6vw, 4.5rem);
    font-weight: 400;
    line-height: 0.97;
    letter-spacing: -0.035em;
    text-wrap: balance;
  }

  h1 .accent {
    display: block;
    color: var(--green);
    font-style: italic;
    padding-right: 0.06em;
  }

  .hero-sub {
    max-width: 34rem;
    margin: 24px 0 0;
    color: var(--ink-2);
    font-size: clamp(1.04rem, 1.4vw, 1.2rem);
    line-height: 1.62;
    text-wrap: pretty;
  }

  .cta-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px;
    margin-top: 32px;
  }

  .hero-note {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 22px 0 0;
    color: var(--ink-3);
    font-size: 0.82rem;
    font-weight: 500;
  }

  .hero-note svg {
    width: 16px;
    height: 16px;
    color: var(--green);
  }

  /* Product preview */
  .hero-visual {
    position: relative;
    min-width: 0;
    padding: 18px 0;
  }

  .hero-visual::before {
    content: '';
    position: absolute;
    z-index: 0;
    top: -13%;
    right: -7%;
    width: 82%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: radial-gradient(circle at 44% 44%, rgba(220, 235, 156, 0.82), rgba(220, 235, 156, 0) 68%);
    opacity: 0.8;
    pointer-events: none;
  }

  .spend-card {
    position: relative;
    z-index: 2;
    padding: 22px;
    border: 1px solid rgba(21, 33, 27, 0.12);
    border-radius: 20px;
    background: var(--card);
    box-shadow: 0 44px 90px -46px rgba(21, 33, 27, 0.55), 0 12px 26px -20px rgba(21, 33, 27, 0.28), 0 1px 0 rgba(255, 255, 255, 0.8) inset;
    transform: rotate(-1.1deg);
  }

  .card-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--line);
  }

  .card-kicker {
    margin: 0 0 4px;
    color: var(--ink-3);
    font-family: var(--font-mono);
    font-size: 0.62rem;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
  }

  .card-title {
    margin: 0;
    font-size: 1.06rem;
    font-weight: 650;
    letter-spacing: -0.02em;
  }

  .sync {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 9px;
    border-radius: 999px;
    background: var(--mint);
    color: var(--green);
    font-size: 0.7rem;
    font-weight: 600;
    white-space: nowrap;
  }

  .sync-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--green);
  }

  .queue {
    display: flex;
    flex-direction: column;
    padding: 8px 0;
  }

  .txn {
    display: grid;
    grid-template-columns: 34px minmax(0, 1fr) auto;
    align-items: center;
    gap: 12px;
    padding: 10px 8px;
    border-radius: 10px;
  }

  .txn + .txn {
    border-top: 1px solid rgba(217, 211, 196, 0.72);
  }

  .txn--flag {
    background: #FBF3E4;
    border-top-color: transparent;
  }

  .txn--flag + .txn {
    border-top-color: transparent;
  }

  .txn-icon {
    display: grid;
    place-items: center;
    width: 34px;
    height: 34px;
    border-radius: 9px;
    background: var(--paper-2);
    color: var(--green);
  }

  .txn-icon svg {
    width: 17px;
    height: 17px;
  }

  .txn-main {
    min-width: 0;
  }

  .txn-main strong,
  .txn-main small {
    display: block;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  .txn-main strong {
    font-size: 0.86rem;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  .txn-main small {
    color: var(--ink-3);
    font-size: 0.71rem;
  }

  .status {
    padding: 5px 8px;
    border-radius: 6px;
    font-size: 0.64rem;
    font-weight: 650;
    letter-spacing: 0.02em;
    white-space: nowrap;
  }

  .status--ok {
    background: var(--mint);
    color: var(--green);
  }

  .status--flag {
    background: var(--amber-bg);
    color: var(--amber);
  }

  .card-foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-top: 16px;
    border-top: 1px solid var(--line);
  }

  .foot-title {
    margin: 0 0 2px;
    font-size: 0.76rem;
    font-weight: 600;
  }

  .foot-sub {
    margin: 0;
    color: var(--ink-3);
    font-size: 0.69rem;
  }

  .export-state {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    color: var(--green);
    font-size: 0.7rem;
    font-weight: 650;
    white-space: nowrap;
  }

  .export-state svg {
    width: 14px;
    height: 14px;
  }

  .float-chip {
    position: absolute;
    z-index: 3;
    top: -5px;
    right: 5px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 9px 12px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 10px;
    background: var(--ink);
    color: var(--paper);
    font-size: 0.71rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    white-space: nowrap;
    box-shadow: 0 16px 30px -18px rgba(21, 33, 27, 0.8);
    transform: rotate(1.7deg);
  }

  .float-chip svg {
    width: 15px;
    height: 15px;
    color: var(--lime);
  }

/* Features */
  .section {
    padding-block: var(--section-pad);
  }

  .section-head {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 0.82fr);
    gap: clamp(24px, 5vw, 80px);
    align-items: end;
    padding-top: 24px;
    border-top: 1px solid var(--line-strong);
  }

  .section-head h2 {
    margin: 0;
  }

  .section-intro {
    max-width: 34rem;
    margin: 0 0 6px;
    justify-self: end;
    color: var(--ink-2);
    font-size: 0.98rem;
    line-height: 1.65;
    text-wrap: pretty;
  }

  .features-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    margin-top: clamp(36px, 5vw, 60px);
    border-top: 1px solid var(--line);
  }

  .feature {
    position: relative;
    padding: 28px clamp(20px, 2.6vw, 32px) 36px 0;
    transition: background-color 0.2s ease;
  }

  .feature:first-child {
    padding-left: 0;
  }

  .feature + .feature {
    border-left: 1px solid var(--line);
    padding-left: clamp(20px, 2.6vw, 32px);
  }

  .feature:hover {
    background: rgba(14, 91, 68, 0.035);
  }

  .feature-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 28px;
  }

  .feature-icon {
    display: grid;
    place-items: center;
    width: 44px;
    height: 44px;
    border-radius: 12px;
    background: var(--mint);
    color: var(--green);
  }

  .feature-icon svg {
    width: 22px;
    height: 22px;
  }

  .feature-num {
    color: var(--ink-3);
    font-family: var(--font-mono);
    font-size: 0.64rem;
    letter-spacing: 0.12em;
  }

  .feature h3 {
    margin: 0 0 10px;
    font-size: 1.25rem;
    font-weight: 650;
    letter-spacing: -0.02em;
  }

  .feature p {
    max-width: 34ch;
    margin: 0;
    color: var(--ink-2);
    font-size: 0.95rem;
    line-height: 1.66;
  }

  /* How it works */
  .how {
    position: relative;
    overflow: clip;
    padding-block: clamp(60px, 7.5vw, 100px);
    border-block: 1px solid #CBD4C6;
    background: var(--sage);
  }

  .how::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background-image: linear-gradient(to right, rgba(14, 91, 68, 0.055) 1px, transparent 1px), linear-gradient(to bottom, rgba(14, 91, 68, 0.055) 1px, transparent 1px);
    background-size: 56px 56px;
    -webkit-mask-image: linear-gradient(to right, #000, transparent 82%);
    mask-image: linear-gradient(to right, #000, transparent 82%);
  }

  .how .wrap {
    position: relative;
    z-index: 1;
  }

  .how-head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 32px;
  }

  .how-head h2 {
    margin: 0;
    font-size: clamp(2rem, 3.7vw, 3rem);
  }

  .how-head > p {
    max-width: 29rem;
    margin: 0 0 5px;
    color: var(--ink-2);
    font-size: 0.95rem;
    line-height: 1.6;
  }

  .steps {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    margin: clamp(40px, 5vw, 64px) 0 0;
    padding: 0;
    list-style: none;
    border-top: 1px solid rgba(14, 91, 68, 0.26);
  }

  .step {
    padding: 26px clamp(20px, 3vw, 40px) 0 0;
  }

  .step + .step {
    border-left: 1px solid rgba(14, 91, 68, 0.18);
    padding-left: clamp(20px, 3vw, 40px);
  }

  .step-head {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 22px;
  }

  .step-num {
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    width: 44px;
    height: 44px;
    border: 1px solid rgba(14, 91, 68, 0.45);
    border-radius: 50%;
    background: var(--sage);
    color: var(--green);
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 600;
  }

  .step-line {
    flex: 1;
    border-top: 1px dashed rgba(14, 91, 68, 0.34);
  }

  .step:last-child .step-line {
    visibility: hidden;
  }

  .step h3 {
    margin: 0 0 8px;
    font-size: 1.12rem;
    font-weight: 650;
    letter-spacing: -0.015em;
  }

  .step p {
    max-width: 32ch;
    margin: 0;
    color: var(--ink-2);
    font-size: 0.92rem;
    line-height: 1.6;
  }

  /* Closing */
  .closing {
    position: relative;
    overflow: clip;
    padding-block: clamp(72px, 9vw, 122px);
    background: var(--green-deep);
    color: var(--paper);
  }

  .closing::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background-image: linear-gradient(to right, rgba(245, 242, 234, 0.045) 1px, transparent 1px), linear-gradient(to bottom, rgba(245, 242, 234, 0.045) 1px, transparent 1px);
    background-size: 64px 64px;
    -webkit-mask-image: linear-gradient(to left, #000, transparent 74%);
    mask-image: linear-gradient(to left, #000, transparent 74%);
  }

  .closing::after {
    content: '';
    position: absolute;
    top: 50%;
    right: -9%;
    width: min(54vw, 680px);
    aspect-ratio: 1;
    border-radius: 50%;
    background: repeating-radial-gradient(circle at center, transparent 0 57px, rgba(220, 235, 156, 0.13) 58px 59px);
    -webkit-mask-image: radial-gradient(circle, #000 26%, transparent 72%);
    mask-image: radial-gradient(circle, #000 26%, transparent 72%);
    transform: translateY(-50%);
    pointer-events: none;
  }

  .closing-inner {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: clamp(32px, 6vw, 88px);
    align-items: end;
    padding-top: 38px;
    border-top: 1px solid rgba(245, 242, 234, 0.18);
  }

  .closing-copy h2 {
    margin: 0;
    color: var(--paper);
    font-size: clamp(2.4rem, 5.2vw, 4.35rem);
    line-height: 1;
  }

  .closing-accent {
    display: block;
    color: var(--lime);
    font-style: italic;
    padding-right: 0.04em;
  }

  .closing-side {
    width: min(100%, 400px);
    padding-bottom: 6px;
  }

  .closing-side p {
    margin: 0 0 24px;
    color: rgba(245, 242, 234, 0.78);
    font-size: 1rem;
    line-height: 1.62;
    text-wrap: pretty;
  }

  .closing .cta-row {
    margin-top: 0;
  }

  /* Footer */
  .site-footer {
    padding: 24px 0 34px;
    border-top: 1px solid var(--line);
    background: var(--paper);
  }

  .footer-inner {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px 26px;
  }

  .footer-brand {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 650;
    letter-spacing: -0.02em;
    text-decoration: none;
  }

  .footer-tag {
    margin: 0;
    color: var(--ink-3);
    font-size: 0.82rem;
  }

  .footer-nav {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 22px;
    margin-left: auto;
  }

  .footer-nav a {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    color: var(--ink-2);
    font-size: 0.82rem;
    text-decoration: none;
  }

  .footer-nav a:hover {
    color: var(--ink);
    text-decoration: underline;
    text-underline-offset: 4px;
  }

  .copyright {
    margin: 0;
    color: var(--ink-3);
    font-size: 0.78rem;
  }

  /* Motion */
  @keyframes sync-pulse {
    0%,
    100% {
      box-shadow: 0 0 0 0 rgba(14, 91, 68, 0.32);
    }
    50% {
      box-shadow: 0 0 0 5px rgba(14, 91, 68, 0);
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    .sync-dot {
      animation: sync-pulse 2.8s ease-in-out infinite;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }
  }

  /* Responsive */
  @media (max-width: 980px) {
    .hero-grid {
      grid-template-columns: 1fr;
      gap: 56px;
    }

    .hero-copy {
      max-width: 660px;
    }

    .hero-visual {
      width: 100%;
      max-width: 520px;
      margin-inline: auto;
    }

    .section-head {
      grid-template-columns: 1fr;
      align-items: start;
      gap: 16px;
    }

    .section-intro {
      justify-self: start;
    }

    .closing-inner {
      grid-template-columns: 1fr;
      align-items: start;
      gap: 30px;
    }

    .closing-side {
      max-width: 460px;
    }
  }

  @media (max-width: 820px) {
    .nav {
      display: none;
    }

    .features-grid {
      grid-template-columns: 1fr;
    }

    .feature {
      padding: 26px 0 30px;
    }

    .feature:first-child {
      padding-top: 28px;
    }

    .feature + .feature {
      border-left: 0;
      border-top: 1px solid var(--line);
      padding-left: 0;
    }

    .feature-top {
      margin-bottom: 18px;
    }

    .feature p {
      max-width: 46ch;
    }

    .how-head {
      flex-direction: column;
      align-items: flex-start;
      gap: 14px;
    }

    .steps {
      grid-template-columns: 1fr;
    }

    .step {
      padding: 24px 0 28px;
    }

    .step + .step {
      border-left: 0;
      border-top: 1px solid rgba(14, 91, 68, 0.18);
      padding-left: 0;
    }

    .step-line {
      display: none;
    }

    .step p {
      max-width: 44ch;
    }
  }

  @media (max-width: 520px) {
    .header-inner {
      min-height: 64px;
      gap: 12px;
    }

    .hero {
      padding-top: 34px;
    }

    .hero-sub {
      margin-top: 20px;
      font-size: 1.02rem;
    }

    .cta-row {
      gap: 10px;
      margin-top: 28px;
    }

    .btn {
      min-height: 46px;
      padding: 0 18px;
    }

    .btn-header {
      padding: 0 14px;
      font-size: 0.79rem;
    }

    .float-chip {
      top: -10px;
      right: 2px;
      padding: 7px 10px;
      font-size: 0.66rem;
    }

    .spend-card {
      padding: 16px;
      border-radius: 16px;
    }

    .txn {
      grid-template-columns: 30px minmax(0, 1fr) auto;
      gap: 9px;
      padding: 9px 4px;
    }

    .txn-icon {
      width: 30px;
      height: 30px;
      border-radius: 8px;
    }

    .txn-icon svg {
      width: 15px;
      height: 15px;
    }

    .txn-main strong {
      font-size: 0.8rem;
    }

    .txn-main small {
      font-size: 0.66rem;
    }

    .status {
      padding: 4px 6px;
      font-size: 0.58rem;
    }

    .card-head {
      padding-bottom: 12px;
    }

    .queue {
      padding: 6px 0;
    }

    .card-foot {
      padding-top: 13px;
    }

    .footer-inner {
      gap: 4px 18px;
    }

    .footer-tag {
      flex-basis: 100%;
      margin-top: -8px;
    }

    .footer-nav {
      margin-left: 0;
      gap: 16px;
    }

    .copyright {
      flex-basis: 100%;
    }
  }
